# Read the current file and make the replacement
with open("src/semver/version.py", "r") as f:
    content = f.read()

old = """        cls = type(self)
        if self._prerelease is not None:
            prerelease = self._prerelease
        elif token == "":
            prerelease = "0"
        elif token is None:
            prerelease = "rc.0"
        else:
            prerelease = str(token) + ".0"

        prerelease = cls._increment_string(prerelease)
        return cls(self._major, self._minor, self._patch, prerelease)"""

new = """        cls = type(self)
        if self._prerelease is not None:
            prerelease = self._prerelease
            # Check if the last dot-separated segment is purely numeric
            last_segment = prerelease.rsplit(".", 1)[-1]
            if last_segment.isdigit():
                prerelease = cls._increment_string(prerelease)
            elif not any(c.isdigit() for c in last_segment):
                # Last segment has no digits; try _increment_string
                prerelease = cls._increment_string(prerelease)
                if prerelease == self._prerelease:
                    prerelease = prerelease + ".0"
            else:
                # Last segment contains digits but isn't purely numeric (e.g., 'rc9')
                prerelease = prerelease + ".0"
            return cls(self._major, self._minor, self._patch, prerelease)
        elif token == "":
            prerelease = "0"
        elif token is None:
            prerelease = "rc.0"
        else:
            prerelease = str(token) + ".0"

        prerelease = cls._increment_string(prerelease)
        return cls(self._major, self._minor, self._patch, prerelease)"""

if old in content:
    print("Found old block, replacing...")
    content = content.replace(old, new, 1)
    with open("src/semver/version.py", "w") as f:
        f.write(content)
    print("Done!")
else:
    print("ERROR: old block not found")
    # Find what's close
    idx = content.find('cls = type(self)')
    while idx >= 0:
        snippet = content[idx:idx+200]
        if 'prerelease' in snippet:
            print(f"Found at {idx}:")
            print(repr(snippet))
            break
        idx = content.find('cls = type(self)', idx+1)
